insert into public.categories (slug, no, title, accent, blurb, care, feature_product_id, sort) values
  ('torans', '01', 'Doorway', 'Torans', 'Stitched bands and hand-cut flaps that dress a doorway for every arrival.', 'Cotton and thread with glass mirrors and metal bells. Dust gently; spot clean only.', 'haveli-toran', 0),
  ('hangings', '02', 'Wall & Door', 'Hangings', 'Mandalas, rings and bell cascades, strung bead by bead.', 'Thread, beads and wood. Keep out of strong direct sun to protect the colours.', 'moon-mandala', 1),
  ('garlands', '03', 'Toran', 'Garlands', 'Soft swags of pom-poms, leaves and tassels for festive days and ordinary ones.', 'Wool, felt and cotton. Shake out gently and store flat between seasons.', 'pompom-swag', 2),
  ('oxidised', '04', 'Oxidised', 'Jewelry', 'Darkened silver-look metal, chased and beaded by hand.', 'Oxidised alloy, nickel-free. Keep dry and store in the cloth pouch it arrives in.', 'temple-jhumka', 3),
  ('gold-silver', '05', 'Gold & Silver-tone', 'Jewelry', 'Warm gold and cool silver finishes on everyday heirloom shapes.', 'Plated alloy, nickel-free. Avoid perfume and water to keep the finish bright.', 'lotus-jhumka', 4)
insert into public.products (id, category_slug, name, mini, description, colors, art, bg, sort) values
  ('haveli-toran', 'torans', 'Haveli Doorway Toran', 'Seven flaps, mirror-stitched band', 'A cotton band edged in running stitch, set with tiny mirrors, and hung with seven pointed flaps. Each flap ends in a small brass-tone bell, so the doorway answers softly when someone walks through.', array['rust','ink','earth','natural']::text[], '{"type":"toran","flaps":7,"shape":"tri","bells":true}'::jsonb, '#EFE2C9', 0),
  ('mirrorwork-toran', 'torans', 'Mirrorwork Scallop Toran', 'Round scallops with tiny mirrors', 'Six rounded scallops, each one framed in chain stitch around a hand-set mirror. A quieter, fuller toran that suits a wide doorway or a bare wall above a bed.', array['ink','rust','natural']::text[], '{"type":"toran","flaps":6,"shape":"round","bells":false}'::jsonb, '#EBD3C3', 1),
  ('leaf-toran', 'torans', 'Mango Leaf Toran', 'Hand-cut leaves, festive welcome', 'Nine fabric leaves, cut and edged by hand, after the mango-leaf torans hung for weddings and new beginnings. Light enough to hang with a single nail.', array['earth','rust','natural']::text[], '{"type":"toran","flaps":9,"shape":"leaf","bells":false}'::jsonb, '#E6D5B4', 2),
  ('bell-toran', 'torans', 'Little Bells Toran', 'Chimes softly when doors open', 'Five flaps with bead strings between them, each string finished with a little bell. Made for the door you use most.', array['rust','earth']::text[], '{"type":"toran","flaps":5,"shape":"tri","bells":true,"strings":2}'::jsonb, '#E4D9C6', 3),
  ('paisley-toran', 'torans', 'Paisley Panel Toran', 'Embroidered paisleys on cotton', 'Five generous paisley panels worked in dense satin stitch. It takes our makers close to a week, and you can see every day of it.', array['ink','rust']::text[], '{"type":"toran","flaps":5,"shape":"leaf","bells":false,"big":true}'::jsonb, '#DCC8A5', 4),
  ('threshold-toran', 'torans', 'Festival Threshold Toran', 'Long tassels, beaded band', 'A beaded band with eight scallops and long cotton tassels that sway in a draught. Our brightest piece, made for festival weeks.', array['rust','natural','ink']::text[], '{"type":"toran","flaps":8,"shape":"round","tassels":true}'::jsonb, '#EFE2C9', 5),
  ('moon-mandala', 'hangings', 'Moon Mandala Hanging', 'Petal mandala with bead strands', 'An eight-petal mandala stitched over a stiffened cotton disc, with five bead strands falling below. Hang it on a door, a wall, or the end of a bookshelf.', array['rust','ink','earth','natural']::text[], '{"type":"hanging","motif":"mandala","strands":5}'::jsonb, '#E6D5B4', 6),
  ('bell-cascade', 'hangings', 'Bell Cascade Hanging', 'Brass bells in falling rows', 'Seven strands of knotted thread, each one carrying a row of little bells that get smaller towards the end. It sounds like rain on a tin roof, quietly.', array['ink','rust','earth']::text[], '{"type":"hanging","motif":"bells","strands":7}'::jsonb, '#EFE2C9', 7),
  ('sunwheel', 'hangings', 'Sunwheel Door Hanging', 'Stitched rays around mirror', 'A round mirror ringed with stitched rays and three short tassel strands. A small, bright piece for a small, dark corner.', array['rust','natural']::text[], '{"type":"hanging","motif":"sun","strands":3}'::jsonb, '#EBD3C3', 8),
  ('twin-ring', 'hangings', 'Twin Ring Hanging', 'Two hoops, thread-wrapped', 'Two wooden hoops, wrapped tightly in thread and joined with a single knot, with bead strands below. Simple and steady.', array['earth','ink','natural']::text[], '{"type":"hanging","motif":"rings","strands":5}'::jsonb, '#E4D9C6', 9),
  ('tassel-fall', 'hangings', 'Tassel Fall Hanging', 'Cotton tassels on wooden bead', 'Five cotton tassels gathered under one carved wooden bead. Our smallest hanging, often bought in pairs for a cupboard or a car mirror.', array['natural','rust']::text[], '{"type":"hanging","motif":"tassels","strands":5}'::jsonb, '#DCC8A5', 10),
  ('seed-bead', 'hangings', 'Seed Bead Wall Hanging', 'Thousands of tiny beads', 'A diamond panel built from thousands of seed beads, stitched one at a time, with seven fringe strands. Heavy, glinting and slow to make.', array['ink','rust','earth']::text[], '{"type":"hanging","motif":"diamond","strands":7}'::jsonb, '#E6D5B4', 11),
  ('pompom-swag', 'garlands', 'Pom-pom Swag Garland', 'Woolly pom-poms, three swags', 'Three soft swags of hand-wound wool pom-poms, with tassels at every join. Drape it over a doorway, a mantel or a window.', array['rust','ink','earth','natural']::text[], '{"type":"garland","style":"pompom","swags":3}'::jsonb, '#EFE2C9', 12),
  ('leaf-bead', 'garlands', 'Leaf & Bead Garland', 'Felt leaves on bead string', 'Felt leaves strung between wooden beads in two easy swags. Pairs well with a toran above the same door.', array['earth','natural','rust']::text[], '{"type":"garland","style":"leaf","swags":2}'::jsonb, '#E4D9C6', 13),
  ('bell-chain', 'garlands', 'Bell Chain Garland', 'Little bells between knots', 'A knotted cord with a little bell between every knot. It moves in the smallest breeze.', array['ink','rust']::text[], '{"type":"garland","style":"bell","swags":2}'::jsonb, '#EBD3C3', 14),
  ('long-latkan', 'garlands', 'Long Latkan Garland', 'Tassels at staggered lengths', 'Latkans, the long beaded tassels of Indian doorways, hung at staggered lengths from a single cord.', array['rust','natural','earth']::text[], '{"type":"garland","style":"latkan"}'::jsonb, '#E6D5B4', 15),
  ('bunting', 'garlands', 'Tassel Bunting Garland', 'Stitched flags, cheerful drape', 'Small stitched cotton flags with a tassel under each one. Light, cheerful and easy to move from room to room.', array['rust','ink','natural']::text[], '{"type":"garland","style":"bunting","swags":2}'::jsonb, '#DCC8A5', 16),
  ('festive-arch', 'garlands', 'Festive Arch Garland', 'One deep swag, many tassels', 'One deep swag, heavy with pom-poms and tassels, sized for a main door or a wedding arch.', array['rust','earth']::text[], '{"type":"garland","style":"pompom","swags":1}'::jsonb, '#EFE2C9', 17),
  ('temple-jhumka', 'oxidised', 'Temple Jhumka', 'Domed bells, beaded fringe', 'Domed jhumkas with a flower stud, a chased band and a fringe of small beads. Light for their size and easy to wear all day.', array['oxidised','oxidised-pearl']::text[], '{"type":"jhumka"}'::jsonb, '#E6D5B4', 18),
  ('crescent-chandbali', 'oxidised', 'Crescent Chandbali', 'Moon-shaped, pearl-edged drops', 'Crescent-moon chandbalis edged with a row of beads, finished dark so the chased detail stands out.', array['oxidised-pearl','oxidised']::text[], '{"type":"chandbali"}'::jsonb, '#E4D9C6', 19),
  ('coin-choker', 'oxidised', 'Tribal Coin Choker', 'Hammered coins on a curve', 'Hammered coins hung along a curved collar, after the old coin necklaces of Rajasthan. Sits close at the base of the neck.', array['oxidised','oxidised-pearl']::text[], '{"type":"necklace","style":"coin"}'::jsonb, '#EFE2C9', 20),
  ('engraved-cuff', 'oxidised', 'Engraved Cuff Bangle', 'Dot-chased, open, adjustable', 'An open cuff, chased with rows of dots by hand. Gently adjustable to fit most wrists.', array['oxidised','oxidised-pearl']::text[], '{"type":"bangle","style":"dots","count":1}'::jsonb, '#EBD3C3', 21),
  ('sun-disc', 'oxidised', 'Sun Disc Pendant', 'Rayed disc, long chain', 'A rayed sun disc with a single bead at its centre, on a long fine chain.', array['oxidised','oxidised-pearl']::text[], '{"type":"pendant","style":"sun"}'::jsonb, '#DCC8A5', 22),
  ('hoop-drops', 'oxidised', 'Little Hoop Drops', 'Everyday hoops with beads', 'Small hoops with three beads hanging at the bottom. The pair our makers wear themselves.', array['oxidised','oxidised-pearl']::text[], '{"type":"hoops"}'::jsonb, '#E6D5B4', 23),
  ('lotus-jhumka', 'gold-silver', 'Lotus Jhumka', 'Lotus stud, bell, fringe', 'A lotus stud above a classic bell, with a bead fringe that catches the light as you move.', array['gold','gold-pearl','silver','silver-pearl']::text[], '{"type":"jhumka","lotus":true}'::jsonb, '#EBD3C3', 24),
  ('filigree-chandbali', 'gold-silver', 'Filigree Chandbali', 'Lace-like crescents, light wear', 'Open filigree crescents, shaped by hand and finished with a beaded edge. Much lighter than they look.', array['gold','gold-pearl','silver','silver-pearl']::text[], '{"type":"chandbali","filigree":true}'::jsonb, '#EFE2C9', 25),
  ('drop-choker', 'gold-silver', 'Teardrop Choker', 'Graduated drops, centre stone', 'Teardrops that grow towards a larger centre stone, along a curved collar. Made for weddings and kept for years.', array['gold','gold-pearl','silver','silver-pearl']::text[], '{"type":"necklace","style":"drops"}'::jsonb, '#E6D5B4', 26),
  ('rope-bangles', 'gold-silver', 'Twisted Rope Bangles', 'A pair, rope-twist finish', 'Two rope-twist bangles, sold as a pair. Wear them together or stacked with others.', array['gold','gold-pearl','silver','silver-pearl']::text[], '{"type":"bangle","style":"rope","count":2}'::jsonb, '#E4D9C6', 27),
  ('coin-pendant', 'gold-silver', 'Old Coin Pendant', 'Stamped coin, fine chain', 'A stamped coin pendant with a beaded rim, on a fine chain.', array['gold','gold-pearl','silver','silver-pearl']::text[], '{"type":"pendant","style":"coin"}'::jsonb, '#DCC8A5', 28),
  ('pearl-hoops', 'gold-silver', 'Pearl Fringe Hoops', 'Hoops dressed in seed pearls', 'Medium hoops with a fringe of beads along the lower curve.', array['gold-pearl','silver-pearl','gold','silver']::text[], '{"type":"hoops","fringe":true}'::jsonb, '#EBD3C3', 29)
